use std::{collections::BTreeMap, fs, path::Path};
use tauri::{
    ipc::{Origin, RuntimeAuthority},
    utils::{
        acl::{capability::Capability, manifest::Manifest, resolved::Resolved},
        platform::Target,
    },
};

fn capability() -> Capability {
    serde_json::from_str(include_str!("../capabilities/default.json")).unwrap()
}

fn authority(capability: Capability) -> RuntimeAuthority {
    // Generated by this application's normal build.rs, not a handcrafted test ACL.
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("gen/schemas/acl-manifests.json");
    let manifests: BTreeMap<String, Manifest> =
        serde_json::from_slice(&fs::read(path).unwrap()).unwrap();
    let capabilities = BTreeMap::from([(capability.identifier.clone(), capability)]);
    let resolved = Resolved::resolve(&manifests, capabilities, Target::Android).unwrap();
    tauri::runtime_authority!(manifests, resolved)
}

const COMMANDS: [&str; 2] = [
    "plugin:floating-window|register_listener",
    "plugin:floating-window|remove_listener",
];

#[test]
fn example_capability_allows_listener_registration_and_removal() {
    let authority = authority(capability());
    for command in COMMANDS {
        assert!(
            authority
                .resolve_access(command, "main", "main", &Origin::Local)
                .is_some(),
            "{command}"
        );
        assert!(authority
            .resolve_access(command, "unrelated", "unrelated", &Origin::Local)
            .is_none());
        let remote = Origin::Remote {
            url: "https://example.com".parse().unwrap(),
        };
        assert!(authority
            .resolve_access(command, "main", "main", &remote)
            .is_none());
    }
}

#[test]
fn core_permission_alone_does_not_allow_floating_window_listeners() {
    let mut capability = capability();
    capability
        .permissions
        .retain(|entry| entry.identifier().get() != "floating-window:default");
    let authority = authority(capability);
    for command in COMMANDS {
        assert!(
            authority
                .resolve_access(command, "main", "main", &Origin::Local)
                .is_none(),
            "{command}"
        );
    }
}
